$ErrorActionPreference='Stop'
$Root=Split-Path -Parent (Split-Path -Parent $MyInvocation.MyCommand.Path)
$Python=Join-Path $Root '.venv\Scripts\pythonw.exe';if(!(Test-Path $Python)){$Python=Join-Path $Root '.venv\Scripts\python.exe'};if(!(Test-Path $Python)){throw "Python runtime not found"}
function Register-HiddenTask{param([string]$Name,[string]$Script,$Trigger,[int]$ExecutionMinutes,[string]$Description);$action=New-ScheduledTaskAction -Execute $Python -Argument "scripts\$Script" -WorkingDirectory $Root;$settings=New-ScheduledTaskSettingsSet -StartWhenAvailable -WakeToRun -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -MultipleInstances IgnoreNew -Hidden -ExecutionTimeLimit (New-TimeSpan -Minutes $ExecutionMinutes);Register-ScheduledTask -TaskName $Name -Action $action -Trigger $Trigger -Settings $settings -Description $Description -Force|Out-Null}
$community=New-ScheduledTaskTrigger -Daily -At '06:20' -RandomDelay (New-TimeSpan -Minutes 20);Register-HiddenTask 'FBAutoposter-CommunityManager' 'community_manager.py' $community 30 'Safely expand and validate Facebook communities'
$guarantee=New-ScheduledTaskTrigger -Daily -At '22:10';$gr=New-ScheduledTaskTrigger -Once -At '22:10' -RepetitionInterval (New-TimeSpan -Minutes 15) -RepetitionDuration (New-TimeSpan -Minutes 45);$guarantee.Repetition=$gr.Repetition;Register-HiddenTask 'FBAutoposter-DailyGuarantee' 'ensure_daily_post.py' $guarantee 25 'Safely create one final post only if today has zero confirmed posts'
$web=New-ScheduledTaskTrigger -Daily -At '23:10';$wr=New-ScheduledTaskTrigger -Once -At '23:10' -RepetitionInterval (New-TimeSpan -Minutes 30) -RepetitionDuration (New-TimeSpan -Minutes 60);$web.Repetition=$wr.Repetition;Register-HiddenTask 'FBAutoposter-WebSLO' 'verify_estateboard_web.py' $web 15 'Verify Facebook permalinks are reflected on EstateBoard Pages'
Get-ScheduledTask -TaskName 'FBAutoposter-CommunityManager','FBAutoposter-DailyGuarantee','FBAutoposter-WebSLO'|Select-Object TaskName,State|Format-Table -AutoSize
